const fs = require('fs');
const axeSrc = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
const store = {};
async function load(file, qs = '') {
  const html = fs.readFileSync('/work/' + file, 'utf8').replace(/<script src[^>]*><\/script>/g, '');
  const dom = new JSDOM(html, { url: 'http://localhost/' + file + qs, runScripts: 'outside-only', pretendToBeVisual: true });
  const w = dom.window;
  // Shared localStorage across pages, dialog + matchMedia stubs
  Object.keys(store).forEach(k => w.localStorage.setItem(k, store[k]));
  w.matchMedia = () => ({ matches: false, addEventListener() {} });
  w.HTMLDialogElement.prototype.showModal = function () { this.open = true; };
  w.HTMLDialogElement.prototype.close = function () { this.open = false; this.dispatchEvent(new w.Event('close')); };
  w.eval(fs.readFileSync('/work/js/data.js', 'utf8') + ';window.COURSES=COURSES;window.DEPARTMENTS=DEPARTMENTS;window.TERMS=TERMS;window.MAX_CREDITS=MAX_CREDITS;');
  w.eval(fs.readFileSync('/work/js/app.js', 'utf8'));
  w.document.dispatchEvent(new w.Event('DOMContentLoaded'));
  w.eval(axeSrc);
